const el=id=>document.getElementById(id);
let selectedFile=null,selectionVersion=0,previewURL=null,locationValue=null,timeSource='unknown',photoOffset=null,cursor=null,observationId=null,saving=false,reading=false,locationVersion=0,timeVersion=0;
const localValue=date=>new Date(date-date.getTimezoneOffset()*60000).toISOString().slice(0,16);
function setBusy(busy){el('save').disabled=busy||reading||!selectedFile;for(const id of ['take','upload','replace','locate','clear'])el(id).disabled=busy;el('fresh').disabled=busy||reading;for(const id of ['time','notes','latitude','longitude'])el(id).disabled=busy;el('camera').disabled=busy;el('library').disabled=busy}
function clearLocation(message='No location attached. Phone location is where you are now, which may differ from an older photo.'){locationVersion++;el('locate').disabled=false;locationValue=null;el('latitude').value='';el('longitude').value='';el('clear').hidden=true;el('location').textContent=message}
function setLocation(value,label){locationValue=value;el('latitude').value=value.latitude;el('longitude').value=value.longitude;el('clear').hidden=false;el('location').textContent=label}
function requestLocation(version,automatic=false){const requestVersion=++locationVersion;if(!navigator.geolocation){el('location').textContent='Phone location is unavailable. You can still save.';return}el('locate').disabled=true;el('location').textContent='Waiting for phone location permission… You may save without it.';navigator.geolocation.getCurrentPosition(position=>{if(version!==selectionVersion||requestVersion!==locationVersion||!selectedFile||saving)return;const c=position.coords;if(!Number.isFinite(c.latitude)||!Number.isFinite(c.longitude)||!Number.isFinite(c.accuracy)||Math.abs(c.latitude)>90||Math.abs(c.longitude)>180||c.accuracy<0||!Number.isFinite(position.timestamp)){el('location').textContent='Phone location was invalid. You can still save.';el('locate').disabled=false;return}const value={latitude:c.latitude,longitude:c.longitude,accuracy:c.accuracy,capturedAt:new Date(position.timestamp).toISOString(),source:'device_at_collection'};setLocation(value,`Phone location now: ${c.latitude.toFixed(5)}, ${c.longitude.toFixed(5)} · accuracy ±${Math.round(c.accuracy)} m`);el('locate').disabled=false},()=>{if(version!==selectionVersion||requestVersion!==locationVersion||saving)return;el('location').textContent=automatic?'Location permission was not granted. Save without location, or add it later before saving.':'Could not get phone location. You can still save without it.';el('locate').disabled=false},{enableHighAccuracy:true,timeout:12000,maximumAge:0})}
function choose(mode){if(saving)return;(mode==='camera'?el('camera'):el('library')).click()}
el('take').onclick=()=>choose('camera');el('upload').onclick=()=>choose('library');el('replace').onclick=()=>choose('camera');
async function select(file,mode){if(!file||saving)return;const version=++selectionVersion;reading=true;const editVersion=++timeVersion;selectedFile=file;observationId=null;el('time').value='';el('notes').value='';el('fresh').checked=false;el('freshRow').hidden=mode!=='camera';timeSource='unknown';photoOffset=null;clearLocation();const locVersion=locationVersion;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=URL.createObjectURL(file);el('preview').src=previewURL;el('selection').hidden=false;el('filename').textContent=`${file.name} · ${Math.round(file.size/1024)} KB`;el('metadata').textContent='Reading photo details…';el('timeNote').textContent='No observation time attached.';el('status').textContent=file.size>10485760?'Choose a photo smaller than 10 MB.':'Preview your photo, then save it.';setBusy(false);
 try{if(file.size>10485760)throw new Error('Photo too large');const meta=await PhotoMetadata.fromFile(file);if(version!==selectionVersion)return;
  if(meta.localTime&&editVersion===timeVersion){const date=new Date(meta.localTime+(meta.offset||''));if(Number.isFinite(date.getTime())){el('time').value=meta.localTime.slice(0,16);timeSource='photo_exif';photoOffset=meta.offset;el('timeNote').textContent=meta.offset?'Photo capture time from EXIF, with embedded time-zone offset.':'Photo capture time from EXIF. Time zone unknown; the photo’s local clock time will be kept.'}}
  if(meta.coordinates&&locVersion===locationVersion){setLocation(meta.coordinates,`Photo GPS: ${meta.coordinates.latitude.toFixed(5)}, ${meta.coordinates.longitude.toFixed(5)} · accuracy not recorded`)}
  el('metadata').textContent=`${el('time').value?'Photo time found':'Photo time unknown'} · ${locationValue?'Photo GPS found':'Location unknown'}. Missing details are optional.`;
 }catch(error){if(version===selectionVersion)el('metadata').textContent='Could not read embedded photo details. You can still save, or edit details.'}finally{if(version===selectionVersion){reading=false;setBusy(false)}}}
for(const [id,mode] of [['camera','camera'],['library','library']])el(id).onchange=()=>{const file=el(id).files[0];el(id).value='';select(file,mode)};
el('time').oninput=()=>{timeVersion++;timeSource=el('time').value?'manual':'unknown';photoOffset=null;el('timeNote').textContent=el('time').value?'Observation time edited by you.':'No observation time attached.'};
el('fresh').onchange=()=>{if(!selectedFile||reading)return;if(el('fresh').checked){if(!el('time').value){timeVersion++;el('time').value=localValue(new Date());timeSource='confirmed_capture';el('timeNote').textContent='Current time, for the capture you confirmed just now.'}if(!locationValue)requestLocation(selectionVersion,true)}else{locationVersion++;if(timeSource==='confirmed_capture'){el('time').value='';timeSource='unknown';el('timeNote').textContent='No observation time attached.'}if(locationValue?.source==='device_at_collection')clearLocation()}};
for(const id of ['latitude','longitude'])el(id).oninput=()=>{locationVersion++;const lat=el('latitude').value,lon=el('longitude').value;locationValue=lat!==''&&lon!==''?{latitude:Number(lat),longitude:Number(lon),accuracy:null,capturedAt:null,source:'manual'}:null;el('clear').hidden=lat===''&&lon==='';el('location').textContent='Coordinates edited by you.'};
el('locate').onclick=()=>requestLocation(selectionVersion,false);
el('clear').onclick=()=>clearLocation('Location removed.');
async function request(url,options){const response=await fetch(url,options);if(!response.ok){let message='Could not access your collection. Please retry.';try{message=(await response.json()).error||message}catch{}throw new Error(message)}return{data:await response.json(),status:response.status}}
function card(item){const article=document.createElement('article'),img=document.createElement('img'),body=document.createElement('div');img.src='/api/observations/'+item.id+'/photo';img.alt='Unidentified flower observation';img.loading='lazy';const badge=document.createElement('span');badge.className='badge';badge.textContent='UNIDENTIFIED';body.append(badge);for(const text of [item.observedLocalTime?item.observedLocalTime.replace('T',' ')+' (photo time; time zone unknown)':item.observedAt?new Date(item.observedAt).toLocaleString():'Observation time unknown',item.location?`${item.location.latitude.toFixed(5)}, ${item.location.longitude.toFixed(5)}${item.location.accuracy==null?' · accuracy unknown':' · ±'+Math.round(item.location.accuracy)+' m'}`:'No location',item.notes]){if(text){const p=document.createElement('p');p.textContent=text;body.append(p)}}const link=document.createElement('a');link.href=img.src;link.target='_blank';link.rel='noopener';link.textContent='Open photo';body.append(link);article.append(img,body);return article}
async function load(append=false){el('refresh').disabled=true;el('more').disabled=true;try{const {data}=await request('/api/observations'+(append&&cursor?'?cursor='+encodeURIComponent(cursor):''));if(!append)el('list').replaceChildren();for(const item of data.items)el('list').append(card(item));if(!el('list').children.length)el('list').textContent='No discoveries yet. Save your first flower.';cursor=data.cursor;el('more').hidden=!cursor}catch(error){el('status').textContent=error.message}finally{el('refresh').disabled=false;el('more').disabled=false}}
el('form').onsubmit=async event=>{event.preventDefault();if(saving||reading)return;const file=selectedFile;if(!file||file.size>10485760){el('status').textContent='Choose a photo smaller than 10 MB.';return}if((el('latitude').value==='')!==(el('longitude').value==='')){el('details').open=true;el('status').textContent='Enter both coordinates, or leave both blank.';return}let observedAt=null;if(el('time').value){const date=new Date(el('time').value+(timeSource==='photo_exif'&&photoOffset?photoOffset:''));if(!Number.isFinite(date.getTime())){el('status').textContent='Check the observation time or leave it blank.';el('details').open=true;return}observedAt=timeSource==='photo_exif'&&!photoOffset?null:date.toISOString()}observationId ||= String(9999999999999-Date.now()).padStart(13,'0')+'-'+crypto.randomUUID();const data=new FormData();data.append('photo',file);data.append('metadata',JSON.stringify({id:observationId,observedAt,observedAtSource:el('time').value?timeSource:'unknown',observedLocalTime:timeSource==='photo_exif'&&!photoOffset?el('time').value:null,notes:el('notes').value,location:locationValue}));saving=true;locationVersion++;setBusy(true);el('status').textContent='Uploading photo… Keep this page open.';try{const result=await request('/api/observations',{method:'POST',body:data});if(previewURL)URL.revokeObjectURL(previewURL);previewURL=null;selectedFile=null;selectionVersion++;el('form').reset();el('selection').hidden=true;el('preview').removeAttribute('src');el('time').value='';timeSource='unknown';photoOffset=null;clearLocation();observationId=null;el('details').open=false;el('status').textContent=result.status===200?'This photo was already saved on an earlier attempt. Its original details were kept.':'Saved privately. Ready for your next discovery.';await load()}catch(error){el('status').textContent=error.message+' Your photo is still selected; you can retry.'}finally{saving=false;setBusy(false)}};
el('refresh').onclick=()=>load();el('more').onclick=()=>load(true);load();
